mapper.select:
SELECT b.id, b.revision, b.file_count, b.created_at, CASE WHEN SUM(e.state='PENDING')=0 THEN 'COMPLETE' ELSE 'OPEN' END AS state, SUM(e.state='IMPORTED') AS imported, SUM(e.state='SKIPPED') AS skipped FROM ( SELECT owner_id, id, revision, file_count, created_at FROM knowledge_text_import_batch WHERE owner_id=#{owner}
AND (created_at < #{cursorTime} OR (created_at=#{cursorTime} AND id < #{cursorId}))
ORDER BY created_at DESC, id DESC LIMIT #{limit} ) b JOIN knowledge_text_import_batch_entry e ON e.owner_id=b.owner_id AND e.batch_id=b.id GROUP BY b.id, b.revision, b.file_count, b.created_at ORDER BY b.created_at DESC, b.id DESC
